import sys

def hamming_distance(a, b):
    return sum(x != y for x, y in zip(a, b))

from itertools import starmap, islice
from operator import add

def perform_operations(N, b, operations):
    tree = [b]
    for l, r in operations:
        tree += (0,) * (r - l)
        tree = list(starmap(add, tree[2 * l:2 * r + 1]))
    return hamming_distance(tuple(islice(tree, 1, None)), b)

def minimize_hamming_distance(N, b, Q, operations):
    operations.sort(key=lambda x: x[0])
    acc = {1: (b[0], b[0], len(operation) if operation[-1][0] != 0 else 1) for operation in operations for _ in range(operation[-1][0] - 1)}
    tree = [b]
    for i, (l, _) in enumerate(operations):
        val = tree[i]
        while Acc[i] and Acc[i][0] < l:
            tree.remove(Acc[i][0])
            Acc[i][0] += 1
            tree.insert(tree.index(val), Acc[i][0])
        tree.append(1 if i >= 1 and i < Q else 0)
    return hamming_distance(tuple(tree), b)

if __name__ == "__main__":
