def shortest_path(start):
    level = [[] for _ in range(N)]
    for i in range(N):
        D[start][i] = 0
    dest = start
    if K == 0:
        return [0] * N
    for next_dest in dest:
        for next_dest_i, edge_dest in enumerate(edges[next_dest]):
            if D[start][edge_dest] < inf:
                D[start][next_dest_i] = min(D[start][next_dest_i], D[start][dest] + 1)
            optimal_path = [D[start][edge_dest]]
            dests = [edge_dest]
            for _ in range(1, K):
                new_dests = []
                for dest_in_path, value in list(zip(dests, optimal_path)):
                    for edge_dest in edges[dest_in_path]:
                        if D[start][edge_dest] < inf:
                            if value + D[start][edge_dest] < D[start][dest_in_path]:
                                D[start][dest_in_path] = value + D[start][edge_dest]
                                new_dests.append(edge_dest)
