from bisect import bisect_left, bisect_right
from collections import Counter

def count_median_pairs(seq, target):
    n = len(seq)
    median_count = [0] * (n + 1)
    med = [None] * n
    start = []

    for i, x in enumerate(seq):
        if x < target:
            median_count[bisect_left(median_count, i)] += 1
        else:
            median_count[bisect_right(median_count, i + 1)] += 1

    for i in range(n):
        if med[i] is None:
            median_count.pop()
        else:
            start.append(i + 1)

    for i in range(n):
        pos = bisect_right(median_count, i + 1)
        if pos < len(median_count):
            median_count[pos] -= 1

        # Binary search for the lower bound
        lb = bisect_left(median_count, i - start[pos])
        if lb < len(median_count):
            cnt = (n - i + i + 1) * (n - i - 1) // 2
        else:
            cnt = 0
        m = (target - seq[i]) * (pos - lb) - cnt

        # Binary search for the upper bound
        ub = pos + 1
        while median_count[ub] == i - start[pos]: ub += 1
        cnt += m + (n - i - 1) * (ub - pos)
        for i_ in range(lb, ub):
            cnt += median_count[i_]
        median_count[ub] = i + 1

    return median_count

def solution(n, target, a):
    total_count = 0
    for i in range(n):
        l, r = i + 1, i + 1
        if a[i] < target:
            l, r = 0, i
        elif a[i] > target:
            l, r = i + 1, len(a)
        sequences = count_median_pairs(a, target)
        cm = Counter()
        rest = [r - l + 1 for r in sequences]
        for rel in rest:
            cm[rel] += 1
        total_count += sum((cm[2 * r - l] for r in rest))
        cm.pop(0)
        if rest and cm[rest[0]] > 0:
            total_count += cm[rest[0]]
    return total_count

if __name__ == "__main__":
    n, m = map(int, input().split())
    a = list(map(int, input().split()))
    print(solution(n, m, a))
