class Tree:
    def __init__(self):
        self.graph = {}

    def add_edge(self, u, v):
        if u not in self.graph:
            self.graph[u] = []
        if v not in self.graph:
            self.graph[v] = []
        self.graph[u].append(v)
        self.graph[v].append(u)

    def dfs(self, node, parent, values):
        smallest = float('inf')
        total = 0
        for neighbor in self.graph[node]:
            if neighbor == parent: continue
            subtree_sum = self.vals[neighbor] + self.dfs(neighbor, node, self.vals)
            if subtree_sum < smallest:
                smallest = subtree_sum
                total = subtree_sum
        self.vals[node] = smallest
        return total

    def query(self, node, type, x, y):
