from collections import defaultdict, deque

class TreeNode:
    def __init__(self, root_val, children=None):
        self.root_val = root_val
        self.children = []
        if children is not None:
            for child in children:
                self.children.append(TreeNode(child['val'], child['form']))
            self.max_range = TreeNode(min(child.max_range for child in self.children))
            self.min_range = TreeNode(max(child.min_range for child in self.children))

def find_min_max(root, values):
    q = deque([(0, root),])
    while q:
        idx, node = q.popleft()
        node.min_range, node.max_range = idx, idx
        if idx < len(values) - 1:
            dx = 1 if values[idx] > values[idx+1] else -1
            node.max_range = TreeNode(max(node.max_range.root_val, 
                    node.root_val + i * dx + values[idx+1] 
                    for i in range(node.max_range.max_val - node.max_range.min_val + 1)), form='>')
            node.min_range = TreeNode(min(node.min_range.root_val + series for series in
                    [(y - node.max_range.root_val) * dx for y in range(node.min_range.min_val, node.max_range.max_val + 1)]), form='<')
        for child, form in zip(node.children, (cmp if child.form == '<' else '>=')(node.max_range.root_val, child.min_range.root_val)):
            if child:
                q.append((idx + len(child.children), child))
        return node

def modify_tree(node, values, root):
    if all(round(node.max_range.root_val + (i + 1) * x) == values[i] for i, x in enumerate(node.max_ranges.abstract)):
        return
    else:
        node.to_tree(values)
        node.max_range = TreeNode(max(child.max_range for child in node.children))
        node.min_range = TreeNode(min(child.min_range for child in node.children))
        if root is not node:
            root.max_range = TreeNode(max(node.max_range.root_val, root.max_range.root_val))
            root.min_range = TreeNode(min(node.min_range.root_val, root.min_range.root_val))

def query_sum(node, values, root):
    if all(round(node.max_range.root_val + i * x) == values[i] for i in range(root.max_range.min_val)):
        return node.root_val
    return sum(node[0].to_tree(x.root_val) if i >= root.min_range.min_val and i <= root.max_range.max_val else node[1].to_tree(x.root_val) for i, x in oracle(node[1].max_range, node[1].min_range, node[1].all_tree))


