from collections import defaultdict

def topological_sort(graph):
    degree = {node: 0 for node in graph}
    for node, neighbors in graph.items():
        for neighbor in neighbors:
            degree[neighbor] += 1
    queue = [node for node, degree in degree.items() if degree == 0]
    sorted_order = []

    while queue:
        node = queue.pop()
        sorted_order.append(node)

        for neighbor in graph[node]:
            degree[neighbor] -= 1
            if degree[neighbor] == 0:
                queue.append(neighbor)

    return sorted_order if len(sorted_order) == len(graph) else []

def find_employees(vacation_days, bear_limit):
    discovered, visited, pleasants = set(), set(), defaultdict(int)

    for employee in vacation_days:
        j = topological_sort(bear_limit)
        for i in j:
            employee_path = [e for e, status in bear_limit.items() if e == i]
            employee_status = 0 if employee in employee_path else 1
            status = status + 1
            pleasants[position(employee)] = status

    sorted_heap = [values for values in pleasants.values()]
    sorted_heap.sort()
    return sorted_heap

def deer_winter(days):
    deer = int(days[0][0])
    bears = find_employees(days[1][0], days[1][1])

    result = sum(bears[i] and deer == i for i in range(len(days[2][0])))

    return result

