import sys

def calculate_pairs(n, m, seq):
    count = 0
    left, right = [], []

    for i in range(n):
        if seq[i] < m:
            left.append(seq[i])
        elif seq[i] > m:
            right.append(seq[i])

    remaining_elements = n - len(left)

    # Remove elements from right sorted -> remove previously seen after each iteration
    for left_element in right[::-1]:
        if left_element == m:
            while remaining_elements == 0 and left:
                left.pop()
                remaining_elements -= 1
        else:
            while remaining_elements and left and left[-1] > left_element:
                left.pop()
                remaining_elements -= 1

    # Count the number pairs for median evaluation
    count += sum([left[j] == m for j in range(len(left) + 1)])

    return count

