import sys

def can_be_pure(s):
    """
    Check if the binary string s can be made pure by deleting some characters.
    """
    if len(s) < 4:
        return s == "0111" or s == "1010"
    for i in range(1, len(s) - 3):
        if s[i:i+3] != "0101" and s[i:i+3] != "1010":
            return True
    return False

def min_deletions(s):
    """
    Find the minimum number of deletions required to make the binary string pure.
    """
    max_deletions = len(s) - can_be_pure(s)
    for i in range(len(s)):
        if can_be_pure(s[:i] + s[i+1:]):
            return min_deletions(s[:i] + s[i+1:])
    return max_deletions

def solve():
