def min_char_to_delete(s):
    dp = [[0 for _ in range(len(s)+1)] for _ in range(2)]  # DP table

    for i in range(1, len(s)+1):
        for j in range(1, len(s)+1):
            if s[i-1] == s[j-1] or i == 1:
                dp[(i % 2)][j] = 0
            else:
                dp[(i % 2)][j] = min(dp[(i-1) % 2][j-1], dp[(i-1) % 2][j]) + 1

    return len(s) - dp[(len(s) % 2)][len(s)]  # Find the minimum number of characters to delete

