import sys

def find_median_and_count(n, m, a):
    count, left_count, right_count = 0, 0, 0
    left_sorted, right_sorted = [], []

    for i in range(n):
        if a[i] <= m:
            left_sorted.append(a[i])
            left_count += 1
        else:
            right_sorted.append(a[i])
            right_count += 1

    median_index = (left_count + right_count) // 2
    lower_bound = median_index - right_count + left_count % 2
    upper_bound = median_index + (right_count - left_count)  # Added runtime complexity

    if n > 2 * m - 1:
        median_index = n // 2
        l_index = n - median_index
        up_bound = median_index + (n - 1) // 2  # Added runtime complexity
    else:
        l_index = n - (left_sorted + right_sorted).index(m) + 1
        up_bound = median_index + (n - (left_sorted + right_sorted).index(m))  # Added runtime complexity

    if lower_bound <= up_bound:
        for i in range(n):
            if a[i] > m:
                count += (n - 1) + left_sorted.index(a[i]) - left_count + right_sorted.index(a[i])

        return count
    else:
        return "Unreachable Median: " + str(m)

