left_signs[node] = max(left_signs[parent], left_signs[parent + 1])
right_signs[node] = max(right_signs[parent], right_signs[parent + 1])
parent_signs[node] = left_signs[parent] + right_signs[parent]
parent_party[node] = left_party + right_party

min_building_orders = min(left_signs[parent_party[node])) * 2 - node + 1
hops = 0
while min_building_orders < 2 and depth[left_party] < depth[node] and depth[left_signs[parent]] < depth[node]:
    hops += 1
    node = left_party
    min_building_orders += 2 ** hops  # We ensure that this sub-tree ends with the smallest left tree by repeating hops.

