import sys

class BishopGame:
    def __init__(self):
        self.piles = [None, None, None]
        self.chosen_pile = 0
        self.choices = [None, None, None]
        self.turn = 'First'

    def play_game(self):
        while self.piles[1] == self.piles[2]:
            self.piles = self.add_chosen_pile()
            self.choices = self.add_choices()
            self.show_piles()
            self.turn = self.switch_turn()

    def add_chosen_pile(self):
        if self.turn == 'First':
            return self.choose_pile()
        else:
            while max(self.piles)%max(self.piles)>0:
                self.piles[1] = (self.piles[1]+1) %self.piles[2]
                self.piles[2] = (self.piles[2]+1) %self.piles[3]
            return self.piles

    def add_choices(self):
        if self.choice == {}:
            return self.flip()
        else:
            return self.invalid_choice()

    def show_piles(self):
        print(' '.join([str(x) for x in self.piles]))

    def choose_pile(self):
        return int(input())

    def switch_turn(self):
        if self.turn == 'First':
            return 'Second'
        else:
            return 'First'

    def show_choice(self):
        print(self.choices)

    def invalid_choice(self):
        return -1

    def flip(self):
        count = 0
        i = 0
        p = self.piles[2]
        while p != 0:
            p = p - self.piles[1]
            count += 1
            i = i + 1
            if i %2 == 0:
                self.chosen_pile = 1
            else:
                self.chosen_pile = 2
        self.choices[0], self.choices[1], self.choices[2] = self.chosen_pile % 3, (self.chosen_pile + 1) % 3, (self.chosen_pile + 2) % 3
        return { 0: self.choices[0], 1: self.choices[1], 2: self.choices[2] }

    def determine_winner(self):
        # Determine if the game has ended or if it's still in progress
        if self.piles[1] == self.piles[2]:
            return True
        elif self.choice is None:
            return False

        if self.choices[0] == self.choices[1] and self.choices[1] == self.choices[2]:
            return True
        return False

